parameters.jsonBody:
={{ {
  campaignCode: 'YOUR_CAMPAIGN_CODE',
  firstName: $json.body.firstName,
  lastName: $json.body.lastName,
  email: $json.body.email,
  phone: String($json.body.phone ?? ''),
  utmSource: $json.body.utm_source || 'website',
  form: { Budget: $json.body.budget, Rooms: $json.body.rooms },
  throwErrorOnClientExists: false
} }}
